// Supabase sends: { type: 'INSERT', record: {...}, table: 'applicants' }
const body = $input.item.json.body || $input.item.json;
const record = body.record || body;

if (!record.phone) {
  // No phone number — skip WhatsApp
  return [];
}

// Normalize phone: remove +91 prefix if present, ensure 10 digits
const phone = record.phone.replace(/^\+?91/, '').replace(/\D/g, '');
if (phone.length !== 10) return [];

return [{
  json: {
    phone: phone,
    full_name: record.full_name || 'Candidate',
    to_number: '91' + phone
  }
}];
